{"file_text": "@page "/chat"
@using sv_ad573115309e4cc38ab0ff85d6f29d68.Components.Chat
@using sv_ad573115309e4cc38ab0ff85d6f29d68.Services
@rendermode InteractiveServer
@inject IChatService ChatService

<PageTitle>Chat</PageTitle>

<div class="chat-layout">
    <ChannelSidebar Channels="_channels"
                    ActiveChannelId="_activeChannelId"
                    OnChannelSelected="HandleChannelSelected" />

    <MessageArea ChannelName="@ActiveChannelName"
                 ChannelDescription="@ActiveChannelDescription"
                 Messages="_messages"
                 ThreadSummaries="_threadSummaries"
                 IsLoadingOlder="_isLoadingOlder"
                 OnOpenThread="HandleOpenThread"
                 OnReact="HandleReact"
                 OnSendMessage="HandleSendMessage"
                 OnLoadOlderMessages="HandleLoadOlderMessages" />

    @if (_threadRootMessage is not null)
    {
        <ThreadPanel RootMessage="_threadRootMessage"
                     Replies="_threadReplies"
                     OnClose="HandleCloseThread"
                     OnSendReply="HandleSendThreadReply" />
    }
</div>

@code {
    private List<Channel> _channels = [];
    private List<Message> _messages = [];
    private List<ThreadSummary> _threadSummaries = [];
    private List<Message> _threadReplies = [];
    private Message? _threadRootMessage;
    private int _activeChannelId;
    private bool _isLoadingOlder;
    private const int PageSize = 30;

    private string ActiveChannelName =>
        _channels.FirstOrDefault(c => c.Id == _activeChannelId)?.Name ?? "";

    private string ActiveChannelDescription =>
        _channels.FirstOrDefault(c => c.Id == _activeChannelId)?.Description ?? "";

    protected override async Task OnInitializedAsync()
    {
        _channels = await ChatService.GetChannelsAsync();
        if (_channels.Count > 0)
        {
            await SelectChannel(_channels[0].Id);
        }
    }

    private async Task HandleChannelSelected(int channelId)
    {
        if (channelId == _activeChannelId) return;
        _threadRootMessage = null;
        _threadReplies = [];
        await SelectChannel(channelId);
    }

    private async Task SelectChannel(int channelId)
    {
        _activeChannelId = channelId;
        _messages = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
        BuildThreadSummaries();
        await ChatService.MarkChannelReadAsync(channelId);

        // Update the channel's unread count locally
        var idx = _channels.FindIndex(c => c.Id == channelId);
        if (idx >= 0)
        {
            var ch = _channels[idx];
            _channels[idx] = ch with { UnreadCount = 0 };
        }
    }

    private async Task HandleSendMessage(string content)
    {
        var msg = await ChatService.SendMessageAsync(_activeChannelId, content, null);
        _messages.Add(msg);
    }

    private async Task HandleOpenThread(int messageId)
    {
        _threadRootMessage = _messages.FirstOrDefault(m => m.Id == messageId);
        if (_threadRootMessage is null) return;
        _threadReplies = await ChatService.GetThreadAsync(messageId);
    }

    private void HandleCloseThread()
    {
        _threadRootMessage = null;
        _threadReplies = [];
    }

    private async Task HandleSendThreadReply(string content)
    {
        if (_threadRootMessage is null) return;
        var reply = await ChatService.SendMessageAsync(_activeChannelId, content, _threadRootMessage.Id);
        _threadReplies.Add(reply);
        UpdateThreadSummary(_threadRootMessage.Id);
    }

    private async Task HandleReact((int MessageId, string Emoji) reaction)
    {
        await ChatService.AddReactionAsync(reaction.MessageId, reaction.Emoji);

        // Optimistically update the UI
        var msg = _messages.FirstOrDefault(m => m.Id == reaction.MessageId);
        if (msg is not null)
        {
            var existing = msg.Reactions.FirstOrDefault(r => r.Emoji == reaction.Emoji);
            if (existing is not null)
            {
                existing.Users.Add("You");
            }
            else
            {
                msg.Reactions.Add(new Reaction(reaction.Emoji, ["You"]));
            }
        }
    }

    private async Task HandleLoadOlderMessages()
    {
        if (_isLoadingOlder) return;
        _isLoadingOlder = true;

        var older = await ChatService.GetMessagesAsync(_activeChannelId, _messages.Count, PageSize);
        if (older.Count > 0)
        {
            _messages.InsertRange(0, older);
            BuildThreadSummaries();
        }

        _isLoadingOlder = false;
    }

    private void BuildThreadSummaries()
    {
        _threadSummaries = _messages
            .Where(m => m.ReplyToId is null)
            .Select(m =>
            {
                var replies = _messages.Where(r => r.ReplyToId == m.Id).ToList();
                return replies.Count > 0
                    ? new ThreadSummary(m.Id, replies.Count, replies.Max(r => r.SentAt))
                    : null;
            })
            .Where(t => t is not null)
            .Cast<ThreadSummary>()
            .ToList();
    }

    private void UpdateThreadSummary(int rootMessageId)
    {
        var idx = _threadSummaries.FindIndex(t => t.RootMessageId == rootMessageId);
        var summary = new ThreadSummary(rootMessageId, _threadReplies.Count, DateTime.Now);
        if (idx >= 0)
            _threadSummaries[idx] = summary;
        else
            _threadSummaries.Add(summary);
    }
}
