@@ -1,0 +1,170 @@
+@page "/chat"
+@using sv_ad573115309e4cc38ab0ff85d6f29d68.Components.Chat
+@using sv_ad573115309e4cc38ab0ff85d6f29d68.Services
+@rendermode InteractiveServer
+@inject IChatService ChatService
+
+<PageTitle>Chat</PageTitle>
+
+<div class="chat-layout">
+    <ChannelSidebar Channels="_channels"
+                    ActiveChannelId="_activeChannelId"
+                    OnChannelSelected="HandleChannelSelected" />
+
+    <MessageArea ChannelName="@ActiveChannelName"
+                 ChannelDescription="@ActiveChannelDescription"
+                 Messages="_messages"
+                 ThreadSummaries="_threadSummaries"
+                 IsLoadingOlder="_isLoadingOlder"
+                 OnOpenThread="HandleOpenThread"
+                 OnReact="HandleReact"
+                 OnSendMessage="HandleSendMessage"
+                 OnLoadOlderMessages="HandleLoadOlderMessages" />
+
+    @if (_threadRootMessage is not null)
+    {
+        <ThreadPanel RootMessage="_threadRootMessage"
+                     Replies="_threadReplies"
+                     OnClose="HandleCloseThread"
+                     OnSendReply="HandleSendThreadReply" />
+    }
+</div>
+
+@code {
+    private List<Channel> _channels = [];
+    private List<Message> _messages = [];
+    private List<ThreadSummary> _threadSummaries = [];
+    private List<Message> _threadReplies = [];
+    private Message? _threadRootMessage;
+    private int _activeChannelId;
+    private bool _isLoadingOlder;
+    private const int PageSize = 30;
+
+    private string ActiveChannelName =>
+        _channels.FirstOrDefault(c => c.Id == _activeChannelId)?.Name ?? "";
+
+    private string ActiveChannelDescription =>
+        _channels.FirstOrDefault(c => c.Id == _activeChannelId)?.Description ?? "";
+
+    protected override async Task OnInitializedAsync()
+    {
+        _channels = await ChatService.GetChannelsAsync();
+        if (_channels.Count > 0)
+        {
+            await SelectChannel(_channels[0].Id);
+        }
+    }
+
+    private async Task HandleChannelSelected(int channelId)
+    {
+        if (channelId == _activeChannelId) return;
+        _threadRootMessage = null;
+        _threadReplies = [];
+        await SelectChannel(channelId);
+    }
+
+    private async Task SelectChannel(int channelId)
+    {
+        _activeChannelId = channelId;
+        _messages = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
+        BuildThreadSummaries();
+        await ChatService.MarkChannelReadAsync(channelId);
+
+        // Update the channel's unread count locally
+        var idx = _channels.FindIndex(c => c.Id == channelId);
+        if (idx >= 0)
+        {
+            var ch = _channels[idx];
+            _channels[idx] = ch with { UnreadCount = 0 };
+        }
+    }
+
+    private async Task HandleSendMessage(string content)
+    {
+        var msg = await ChatService.SendMessageAsync(_activeChannelId, content, null);
+        _messages.Add(msg);
+    }
+
+    private async Task HandleOpenThread(int messageId)
+    {
+        _threadRootMessage = _messages.FirstOrDefault(m => m.Id == messageId);
+        if (_threadRootMessage is null) return;
+        _threadReplies = await ChatService.GetThreadAsync(messageId);
+    }
+
+    private void HandleCloseThread()
+    {
+        _threadRootMessage = null;
+        _threadReplies = [];
+    }
+
+    private async Task HandleSendThreadReply(string content)
+    {
+        if (_threadRootMessage is null) return;
+        var reply = await ChatService.SendMessageAsync(_activeChannelId, content, _threadRootMessage.Id);
+        _threadReplies.Add(reply);
+        UpdateThreadSummary(_threadRootMessage.Id);
+    }
+
+    private async Task HandleReact((int MessageId, string Emoji) reaction)
+    {
+        await ChatService.AddReactionAsync(reaction.MessageId, reaction.Emoji);
+
+        // Optimistically update the UI
+        var msg = _messages.FirstOrDefault(m => m.Id == reaction.MessageId);
+        if (msg is not null)
+        {
+            var existing = msg.Reactions.FirstOrDefault(r => r.Emoji == reaction.Emoji);
+            if (existing is not null)
+            {
+                existing.Users.Add("You");
+            }
+            else
+            {
+                msg.Reactions.Add(new Reaction(reaction.Emoji, ["You"]));
+            }
+        }
+    }
+
+    private async Task HandleLoadOlderMessages()
+    {
+        if (_isLoadingOlder) return;
+        _isLoadingOlder = true;
+
+        var older = await ChatService.GetMessagesAsync(_activeChannelId, _messages.Count, PageSize);
+        if (older.Count > 0)
+        {
+            _messages.InsertRange(0, older);
+            BuildThreadSummaries();
+        }
+
+        _isLoadingOlder = false;
+    }
+
+    private void BuildThreadSummaries()
+    {
+        _threadSummaries = _messages
+            .Where(m => m.ReplyToId is null)
+            .Select(m =>
+            {
+                var replies = _messages.Where(r => r.ReplyToId == m.Id).ToList();
+                return replies.Count > 0
+                    ? new ThreadSummary(m.Id, replies.Count, replies.Max(r => r.SentAt))
+                    : null;
+            })
+            .Where(t => t is not null)
+            .Cast<ThreadSummary>()
+            .ToList();
+    }
+
+    private void UpdateThreadSummary(int rootMessageId)
+    {
+        var idx = _threadSummaries.FindIndex(t => t.RootMessageId == rootMessageId);
+        var summary = new ThreadSummary(rootMessageId, _threadReplies.Count, DateTime.Now);
+        if (idx >= 0)
+            _threadSummaries[idx] = summary;
+        else
+            _threadSummaries.Add(summary);
+    }
+}
+

toolArgs.file_text:
.chat-layout {
    display: flex;
    height: 100vh;
    overflow: hidden;
}

/* Channel Sidebar */
.channel-sidebar {
    width: 20%;
    min-width: 200px;
    background: #2b2d31;
    color: #b5bac1;
    display: flex;
    flex-direction: column;
    border-right: 1px solid #1e1f22;
}

.sidebar-title {
    padding: 16px;
    margin: 0;
    font-size: 1rem;
    color: #f2f3f5;
    border-bottom: 1px solid #1e1f22;
}

.channel-list {
    list-style: none;
    padding: 8px;
    margin: 0;
    overflow-y: auto;
    flex: 1;
}

.channel-item {
    padding: 8px 12px;
    border-radius: 4px;
    cursor: pointer;
    margin-bottom: 2px;
}

.channel-item:hover {
    background: #35373c;
}

.channel-item.active {
    background: #404249;
    color: #f2f3f5;
}

.channel-name {
    display: flex;
    justify-content: space-between;
    align-items: center;
    font-weight: 500;
}

.unread-badge {
    background: #f23f43;
    color: #fff;
    font-size: 0.7rem;
    padding: 1px 6px;
    border-radius: 10px;
    font-weight: 700;
}

.channel-description {
    font-size: 0.75rem;
    color: #80848e;
    margin-top: 2px;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

/* Message Area */
.message-area {
    flex: 1;
    display: flex;
    flex-direction: column;
    background: #313338;
    min-width: 0;
}

.message-area-header {
    padding: 12px 16px;
    border-bottom: 1px solid #3f4147;
    background: #313338;
}

.message-area-header h2 {
    margin: 0;
    font-size: 1rem;
    color: #f2f3f5;
}

.channel-desc {
    margin: 2px 0 0;
    font-size: 0.8rem;
    color: #80848e;
}

.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 16px;
}

.loading-indicator {
    text-align: center;
    padding: 8px;
    color: #80848e;
    font-size: 0.85rem;
}

/* Message Item */
.message-item {
    padding: 8px 12px;
    border-radius: 4px;
    position: relative;
    margin-bottom: 4px;
}

.message-item.hovered {
    background: #2e3035;
}

.message-header {
    display: flex;
    align-items: baseline;
    gap: 8px;
}

.message-author {
    font-weight: 600;
    color: #f2f3f5;
    font-size: 0.9rem;
}

.message-time {
    font-size: 0.7rem;
    color: #80848e;
}

.message-content {
    color: #dbdee1;
    margin: 4px 0;
    font-size: 0.9rem;
    line-height: 1.4;
}

.message-reactions {
    display: flex;
    gap: 4px;
    margin-top: 4px;
    flex-wrap: wrap;
}

.reaction-badge {
    background: #2b2d31;
    border: 1px solid #3f4147;
    border-radius: 4px;
    padding: 2px 6px;
    font-size: 0.8rem;
    color: #dbdee1;
    cursor: default;
}

.thread-link {
    background: none;
    border: none;
    color: #00a8fc;
    font-size: 0.8rem;
    cursor: pointer;
    padding: 4px 0;
    font-weight: 500;
}

.thread-link:hover {
    text-decoration: underline;
}

.message-actions {
    position: absolute;
    top: -8px;
    right: 8px;
    display: flex;
    gap: 4px;
    background: #2b2d31;
    border: 1px solid #3f4147;
    border-radius: 4px;
    padding: 2px;
}

.action-btn {
    background: none;
    border: none;
    color: #b5bac1;
    font-size: 0.75rem;
    padding: 4px 8px;
    cursor: pointer;
    border-radius: 3px;
}

.action-btn:hover {
    background: #404249;
    color: #f2f3f5;
}

/* Emoji Picker */
.emoji-picker {
    display: flex;
    gap: 4px;
    background: #2b2d31;
    border: 1px solid #3f4147;
    border-radius: 4px;
    padding: 6px;
    margin-top: 4px;
    width: fit-content;
}

.emoji-option {
    background: none;
    border: none;
    font-size: 1.2rem;
    cursor: pointer;
    padding: 4px;
    border-radius: 4px;
}

.emoji-option:hover {
    background: #404249;
}

/* Message Input Area */
.message-input-area,
.thread-input-area {
    padding: 12px 16px;
    border-top: 1px solid #3f4147;
    display: flex;
    gap: 8px;
    align-items: flex-end;
}

.message-input-area textarea,
.thread-input-area textarea {
    flex: 1;
    resize: none;
    background: #383a40;
    border: none;
    border-radius: 8px;
    padding: 10px 12px;
    color: #dbdee1;
    font-size: 0.9rem;
    font-family: inherit;
    outline: none;
}

.message-input-area textarea:focus,
.thread-input-area textarea:focus {
    box-shadow: 0 0 0 1px #5865f2;
}

.send-btn {
    background: #5865f2;
    color: #fff;
    border: none;
    border-radius: 4px;
    padding: 8px 16px;
    font-weight: 600;
    cursor: pointer;
    font-size: 0.85rem;
}

.send-btn:hover:not(:disabled) {
    background: #4752c4;
}

.send-btn:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

/* Thread Panel */
.thread-panel {
    width: 25%;
    min-width: 250px;
    background: #2b2d31;
    border-left: 1px solid #1e1f22;
    display: flex;
    flex-direction: column;
    color: #dbdee1;
}

.thread-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 12px 16px;
    border-bottom: 1px solid #3f4147;
}

.thread-header h3 {
    margin: 0;
    color: #f2f3f5;
    font-size: 1rem;
}

.close-btn {
    background: none;
    border: none;
    color: #b5bac1;
    font-size: 1.5rem;
    cursor: pointer;
    padding: 0 4px;
    line-height: 1;
}

.close-btn:hover {
    color: #f2f3f5;
}

.thread-root-message {
    padding: 12px 16px;
    border-bottom: 1px solid #3f4147;
    background: #232428;
}

.thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 12px 16px;
}

.thread-reply {
    margin-bottom: 12px;
    padding-bottom: 8px;
    border-bottom: 1px solid #3f4147;
}

.thread-reply:last-child {
    border-bottom: none;
}

